import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  Button,
  FormActions,
  FormRowCol,
  FormSkeleton,
  Input,
  LabelMoney,
  MoneyInput,
  SearchInput,
  Select,
  dispatchAppToast,
  localInputToISOWithOffset,
} from '@linm-soft-org/linm-web-common-components';
import type { ActiveCompanyItem } from '@linm-soft-org/linm-web-common-components';
import { fpcService } from '../../../services/fpc/service';
import { companyService } from '../../../services/company/companyService';
import { useAppDispatch } from '../../../store/hooks';
import { createCompanySearchConfig } from '../../../components/search/companySearchConfig';
import {
  createExpenseItemSearchConfig,
  fetchExpenseItems,
  type ExpenseItemLookupItem,
} from '../../../components/search/costCodeSearchConfig';
import { resolvePlanVoucherDefaultBranchCode } from './resolvePlanVoucherDefaultBranch';
import type { CostPlanItemDto, PlanScheduleType, PlanVoucherDraftDto, PriorityClassDto, ScheduleKind } from '../../../services/fpc/types';
import styles from './PlanVoucherPage.module.css';

declare global {
  interface Window {
    __LINM_UPDATE_TAB_TITLE__?: (title: string) => void;
    __LINM_IS_CURRENT_TAB_DIRTY__?: boolean;
  }
}

const TEST_ID = 'plan-voucher';

const todayDateStr = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};

const HEADER_5COL = { large: [5] as number[], medium: [3, 2] as number[], small: [2, 1, 1, 1] as number[] };

const SCHEDULE_KIND_OPTIONS: { value: ScheduleKind; label: string }[] = [
  { value: 'fixed', label: 'Lịch cố định' },
  { value: 'recurring', label: 'Lịch định kỳ' },
];

const RECURRING_FREQ_OPTIONS: { value: PlanScheduleType; label: string }[] = [
  { value: 'ByDay', label: 'Lặp lại theo ngày' },
  { value: 'ByDayOfWeek', label: 'Lặp lại theo tuần' },
  { value: 'ByDayOfMonth', label: 'Lặp lại theo tháng' },
  { value: 'ByDayOfYear', label: 'Lặp lại theo năm' },
];

const WEEKDAY_OPTIONS = [
  { value: '1', label: 'T2' },
  { value: '2', label: 'T3' },
  { value: '3', label: 'T4' },
  { value: '4', label: 'T5' },
  { value: '5', label: 'T6' },
  { value: '6', label: 'T7' },
  { value: '7', label: 'CN' },
];

const MONTH_MODE_OPTIONS = [
  { value: 'Last', label: 'Ngày cuối tháng' },
  { value: 'Day', label: 'Ngày cụ thể (1–28)' },
];

function toScheduleKind(type: PlanScheduleType | string): ScheduleKind {
  return type === 'Once' ? 'fixed' : 'recurring';
}

function scheduleTypeLabel(type: PlanScheduleType | string): string {
  if (type === 'Once') return 'Lịch cố định';
  return RECURRING_FREQ_OPTIONS.find(o => o.value === type)?.label ?? type;
}

/** Clicks on lookup inputs must not steal focus to `<tr>` — breaks SearchInput dropdown. */
function isLineRowFieldTarget(target: HTMLElement): boolean {
  return !!target.closest(
    'input, textarea, select, button, a, [role="option"], [role="listbox"], [data-search-dropdown], label',
  );
}

function toDateInput(iso?: string | null): string {
  if (!iso) return todayDateStr();
  return iso.substring(0, 10);
}

function monthEndDateStr(year: number, month: number): string {
  const last = new Date(year, month, 0).getDate();
  return `${year}-${String(month).padStart(2, '0')}-${String(last).padStart(2, '0')}`;
}

function scheduleValueLabel(type: PlanScheduleType | string, value?: string | null): string {
  if (type === 'Once' || type === 'ByDay') return type === 'Once' ? 'Một lần' : 'Mỗi ngày';
  if (!value) return '—';
  if (type === 'ByDayOfWeek') {
    return value.split(',').map(v => WEEKDAY_OPTIONS.find(o => o.value === v.trim())?.label ?? v).join(', ');
  }
  if (type === 'ByDayOfMonth') {
    return value === 'Last' ? 'Ngày cuối tháng' : `Ngày ${value}`;
  }
  return value;
}

function needsScheduleValue(type: PlanScheduleType | string): boolean {
  return type !== 'Once' && type !== 'ByDay';
}

/* ── Processing level options ───────────── */
const PROCESSING_LEVEL_OPTIONS = [
  { value: '1', label: 'Mức 1: Nhập liệu' },
  { value: '5', label: 'Mức 5: Kiểm tra' },
  { value: '9', label: 'Mức 9: Hoạch toán' },
];

/* ── RequiredMark component ──────────────── */
const RequiredMark: React.FC = () => (
  <span className={styles.requiredMark} aria-hidden="true">*</span>
);

/* ── Format helpers ──────────────────────── */
const fVnd = (v: number): string =>
  new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(v);

/* ── Types ────────────────────────────────── */
type PlanTab = 'revenue' | 'expense';
type VoucherType = 'doi-tuong' | 'cua-hang' | 'ma-chi-phi';

const VOUCHER_TYPE_OPTIONS: { value: VoucherType; label: string }[] = [
  { value: 'doi-tuong', label: 'Đối tượng' },
  { value: 'cua-hang', label: 'Cửa hàng' },
  { value: 'ma-chi-phi', label: 'Mã chi phí' },
];

interface PlanLine {
  id: string;
  entityCode: string;
  entityName: string;
  entityGroup: string;
  plannedAmount: number;
  actualAmount: number;
  mustPay: number;
  debt: number;
  priority: string;
  useCustomSchedule: boolean;
  effectiveFrom: string;
  effectiveTo: string;
  planScheduleType: PlanScheduleType;
  scheduleValue: string;
}

function mapCostPlanToLine(p: CostPlanItemDto): PlanLine {
  return {
    id: p.id,
    entityCode: p.costCode,
    entityName: p.costCodeName || p.costCode,
    entityGroup: p.groupName || 'Khác',
    plannedAmount: p.plannedAmount,
    actualAmount: p.actualAmount,
    mustPay: p.mustPay,
    debt: p.debt,
    priority: p.priority || '',
    useCustomSchedule: !!p.useCustomSchedule,
    effectiveFrom: toDateInput(p.effectiveFrom),
    effectiveTo: toDateInput(p.effectiveTo),
    planScheduleType: (p.planScheduleType as PlanScheduleType) || 'ByDay',
    scheduleValue: p.scheduleValue || '',
  };
}

function resolvePriorityMeta(
  code: string,
  catalog: PriorityClassDto[],
): { label: string; color: string; background: string } {
  const hit = catalog.find(p => p.code === code);
  if (hit) {
    return { label: hit.name, color: hit.color, background: hit.backgroundColor };
  }
  return { label: code || '—', color: '#6b7280', background: '#f3f4f6' };
}

function entityColumnTitle(voucherType: VoucherType, activeTab: PlanTab): string {
  if (voucherType === 'doi-tuong') return 'Đối tượng';
  if (voucherType === 'cua-hang') return 'Cửa hàng';
  return activeTab === 'revenue' ? 'Khoản thu' : 'Khoản chi';
}

function entityLookupPlaceholder(voucherType: VoucherType): string {
  if (voucherType === 'doi-tuong') return 'Đối tượng...';
  if (voucherType === 'cua-hang') return 'Cửa hàng...';
  return 'Mã CP...';
}

function makeEmptyPlanLine(tab: PlanTab, id: string): PlanLine {
  const from = todayDateStr();
  const y = new Date().getFullYear();
  const m = new Date().getMonth() + 1;
  return {
    id,
    entityCode: '',
    entityName: '',
    entityGroup: tab === 'revenue' ? 'Thu' : 'Chi',
    plannedAmount: 0,
    actualAmount: 0,
    mustPay: 0,
    debt: 0,
    priority: 'Medium',
    useCustomSchedule: false,
    effectiveFrom: from,
    effectiveTo: monthEndDateStr(y, m),
    planScheduleType: 'ByDay',
    scheduleValue: '',
  };
}

/* ── Component ────────────────────────────── */
const PlanVoucherPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const isCreate = !id || id === 'new';

  /* ── Period state ──────────────────────── */
  const now = new Date();
  const [planYear, setPlanYear] = useState(now.getFullYear());
  const [planMonth, setPlanMonth] = useState(now.getMonth() + 1);

  /* ── Voucher entity ────────────────────── */
  const [voucher, setVoucher] = useState<PlanVoucherDraftDto | null>(null);
  const [voucherLoading, setVoucherLoading] = useState(!isCreate);

  /* ── Data state ────────────────────────── */
  /** Danh mục chi phí Master (`/dm/chi-phi`) — lookup dòng */
  const [expenseItems, setExpenseItems] = useState<ExpenseItemLookupItem[]>([]);
  const [priorityClasses, setPriorityClasses] = useState<PriorityClassDto[]>([]);
  const [costPlans, setCostPlans] = useState<CostPlanItemDto[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadedPeriod, setLoadedPeriod] = useState({ year: 0, month: 0 });
  const branchInitDone = useRef(false);

  /* ── UI state ──────────────────────────── */
  const [activeTab, setActiveTab] = useState<PlanTab>('expense');
  const [voucherType, setVoucherType] = useState<VoucherType>('ma-chi-phi');
  const [editMode, setEditMode] = useState(true); // default edit mode
  const [saving, setSaving] = useState(false);
  const [editedLines, setEditedLines] = useState<Record<string, number>>(() =>
    (isCreate ? { 'local-1': 0 } : {}) as Record<string, number>,
  );
  const [editedMustPay, setEditedMustPay] = useState<Record<string, number>>(() =>
    (isCreate ? { 'local-1': 0 } : {}) as Record<string, number>,
  );
  const [editedNotes, setEditedNotes] = useState<Record<string, string>>(() =>
    (isCreate ? { 'local-1': '' } : {}) as Record<string, string>,
  );
  const [editedPriority, setEditedPriority] = useState<Record<string, string>>(() =>
    (isCreate ? { 'local-1': 'Medium' } : {}) as Record<string, string>,
  );
  const [selectedLineIndex, setSelectedLineIndex] = useState(isCreate ? 0 : -1);

  /* ── Processing level ──────────────────── */
  const [processingLevel, setProcessingLevel] = useState('1');

  /* ── Local add/delete — per tab (keep lines when switch) ── */
  const localIdCounter = useRef(isCreate ? 1 : 0);
  const [localAddedByTab, setLocalAddedByTab] = useState<Record<PlanTab, PlanLine[]>>(() => ({
    revenue: [],
    expense: isCreate
      ? [makeEmptyPlanLine('expense', 'local-1')]
      : [],
  }));
  const [localDeletedByTab, setLocalDeletedByTab] = useState<Record<PlanTab, Set<string>>>({
    revenue: new Set(),
    expense: new Set(),
  });

  const localAddedLines = localAddedByTab[activeTab];
  const localDeletedIds = localDeletedByTab[activeTab];

  const setLocalAddedLines = useCallback((updater: PlanLine[] | ((prev: PlanLine[]) => PlanLine[])) => {
    setLocalAddedByTab(prev => ({
      ...prev,
      [activeTab]: typeof updater === 'function' ? updater(prev[activeTab]) : updater,
    }));
  }, [activeTab]);

  const setLocalDeletedIds = useCallback((updater: Set<string> | ((prev: Set<string>) => Set<string>)) => {
    setLocalDeletedByTab(prev => ({
      ...prev,
      [activeTab]: typeof updater === 'function' ? updater(prev[activeTab]) : updater,
    }));
  }, [activeTab]);

  const clearAllLocalLines = useCallback(() => {
    setLocalAddedByTab({ revenue: [], expense: [] });
    setLocalDeletedByTab({ revenue: new Set(), expense: new Set() });
    setScheduleOverrides({});
  }, []);

  /* ── Voucher header state ──────────────── */
  const [voucherCode, setVoucherCode] = useState(isCreate
    ? `PKH-${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}-0001`
    : '');
  const [voucherDate, setVoucherDate] = useState(todayDateStr());
  const [effectiveFrom, setEffectiveFrom] = useState(todayDateStr());
  const [effectiveTo, setEffectiveTo] = useState(() => monthEndDateStr(now.getFullYear(), now.getMonth() + 1));
  const [planScheduleType, setPlanScheduleType] = useState<PlanScheduleType>('ByDay');
  const [scheduleValue, setScheduleValue] = useState('');
  /** In-place schedule edits — cấm promote line → cuối bảng khi tick Lịch riêng */
  const [scheduleOverrides, setScheduleOverrides] = useState<Record<string, Partial<PlanLine>>>({});
  const [description, setDescription] = useState('');

  const scheduleKind = toScheduleKind(planScheduleType);

  /* ── Branch filter state ───────────────── */
  const [branchCode, setBranchCode] = useState('');
  const [selectedCompany, setSelectedCompany] = useState<ActiveCompanyItem | null>(null);

  /* ── Header compact state ──────────────── */
  const [headerExpanded, setHeaderExpanded] = useState(true);

  /* ── Load voucher (edit mode) ──────────── */
  useEffect(() => {
    if (!isCreate && id && id !== 'new') {
      setVoucherLoading(true);
      fpcService.getPlanVoucherById(id)
        .then(v => {
          setVoucher(v);
          setVoucherCode(v.code);
          setVoucherDate(v.voucherDate.substring(0, 10));
          setPlanYear(v.planYear);
          setPlanMonth(v.planMonth);
          setEffectiveFrom(toDateInput(v.effectiveFrom) || `${v.planYear}-${String(v.planMonth).padStart(2, '0')}-01`);
          setEffectiveTo(toDateInput(v.effectiveTo) || monthEndDateStr(v.planYear, v.planMonth));
          setPlanScheduleType((v.planScheduleType as PlanScheduleType) || 'ByDay');
          setScheduleValue(v.scheduleValue || '');
          setDescription(v.description || '');
          setBranchCode(v.branchCode);
        })
        .catch(() => {
          dispatchAppToast(dispatch, { message: 'Không tìm thấy phiếu kế hoạch', type: 'error' });
        })
        .finally(() => setVoucherLoading(false));
    }
  }, [id, isCreate, dispatch]);

  /* ── Tab title sync + dirty flag ────────── */
  const tabTitle = isCreate
    ? 'Tạo phiếu kế hoạch'
    : (voucherCode ? `Phiếu ${voucherCode}` : 'Phiếu kế hoạch');

  useEffect(() => {
    if (voucherCode && typeof window.__LINM_UPDATE_TAB_TITLE__ === 'function') {
      window.__LINM_UPDATE_TAB_TITLE__(tabTitle);
    }
  }, [tabTitle, voucherCode]);

  useEffect(() => {
    window.__LINM_IS_CURRENT_TAB_DIRTY__ = editMode;
    return () => { window.__LINM_IS_CURRENT_TAB_DIRTY__ = false; };
  }, [editMode]);

  /* ── Search configs ────────────────────── */
  const companySearchConfig = useMemo(() => createCompanySearchConfig(), []);

  const objectSearchConfig = useMemo(() => {
    return createCompanySearchConfig();
  }, []);

  const costCodeSearchConfig = useMemo(
    () => createExpenseItemSearchConfig(expenseItems),
    [expenseItems],
  );

  /** Zone A dual mã+tên — parity PT CustomerSearchField (code ≤150px + name) */
  const lineLookupClassName = [
    styles.embeddedSearch,
    styles.lookupCodeMax150,
    styles.lookupDualInline,
    styles.lookupDualRow,
  ].join(' ');

  const headerLookupClassName = lineLookupClassName;

  /* ── Default Chi nhánh = tập đoàn FM (VoucherRegistryFieldDefaults) — cấm active FM01 ── */
  useEffect(() => {
    if (!isCreate || branchInitDone.current) return;
    branchInitDone.current = true;
    let cancelled = false;
    (async () => {
      try {
        const list = await companyService.getActiveList();
        const { code, company } = await resolvePlanVoucherDefaultBranchCode(list);
        if (cancelled) return;
        setBranchCode(code);
        setSelectedCompany(company);
      } catch {
        if (!cancelled) {
          setBranchCode('FM');
          setSelectedCompany({ id: 'FM', code: 'FM', name: 'FM' });
        }
      }
    })();
    return () => { cancelled = true; };
  }, [isCreate]);

  /* ── Fetch catalog + plans (không refetch khi đổi Chi nhánh trên form) ── */
  const fetchData = useCallback(async (year: number, month: number, branch?: string) => {
    setLoading(true);
    try {
      const [items, plans, priorities] = await Promise.all([
        fetchExpenseItems(),
        fpcService.getCostPlanList({ year, month, branchCode: branch || undefined }),
        fpcService.getPriorityClassList(),
      ]);
      setExpenseItems(items);
      setPriorityClasses(priorities.filter(p => p.isActive));
      setCostPlans(plans);
      setLoadedPeriod({ year, month });
    } catch {
      dispatchAppToast(dispatch, { message: 'Không thể tải dữ liệu kế hoạch', type: 'error' });
    } finally {
      setLoading(false);
    }
  }, [dispatch]);

  useEffect(() => {
    if (isCreate) {
      fetchData(planYear, planMonth);
    }
  }, [fetchData, planYear, planMonth, isCreate]);

  useEffect(() => {
    if (!isCreate && voucher) {
      fetchData(voucher.planYear, voucher.planMonth, voucher.branchCode || undefined);
    }
  }, [fetchData, isCreate, voucher]);

  /* ── Schedule / period change ──────────── */
  const syncPeriodFromFrom = (from: string) => {
    const [ys, ms] = from.split('-');
    const year = parseInt(ys, 10) || now.getFullYear();
    const month = parseInt(ms, 10) || now.getMonth() + 1;
    setPlanYear(year);
    setPlanMonth(month);
    return { year, month };
  };

  const handleEffectiveFromChange = (from: string) => {
    setEffectiveFrom(from);
    const { year, month } = syncPeriodFromFrom(from);
    if (effectiveTo < from) setEffectiveTo(monthEndDateStr(year, month));
    setEditedLines({});
    setEditedMustPay({});
    setEditedNotes({});
    setEditedPriority({});
    clearAllLocalLines();
  };

  const handlePeriodChange = (year: number, month: number) => {
    setPlanYear(year);
    setPlanMonth(month);
    const from = `${year}-${String(month).padStart(2, '0')}-01`;
    setEffectiveFrom(from);
    setEffectiveTo(monthEndDateStr(year, month));
    setEditedLines({});
    setEditedMustPay({});
    setEditedNotes({});
    setEditedPriority({});
    clearAllLocalLines();
    setDescription(`Kế hoạch tài chính tháng ${month}/${year}`);
  };

  /* ── Branch change — chỉ cập nhật field; không reload / không xóa dòng ── */
  const handleBranchChange = (item: ActiveCompanyItem | null) => {
    const code = item?.code ?? item?.id ?? '';
    setBranchCode(code);
    setSelectedCompany(item);
  };

  /* ── Revenue lines ─────────────────────── */
  const revenueLines = useMemo((): PlanLine[] => {
    // Master expense-items = chi phí; tab Thu giữ plans đã gắn (nếu có) + dòng local
    return costPlans
      .filter(p => (p.groupName || '').toLowerCase().includes('thu')
        || (p.groupName || '').toLowerCase().includes('doanh thu')
        || (p.priority || '') === 'Income')
      .map(mapCostPlanToLine);
  }, [costPlans]);

  /* ── Expense lines ─────────────────────── */
  const expenseLines = useMemo((): PlanLine[] => {
    const expenseCodes = new Set(expenseItems.map(c => c.code));
    return costPlans
      .filter(p => expenseCodes.size === 0 || expenseCodes.has(p.costCode)
        || !(
          (p.groupName || '').toLowerCase().includes('thu')
          || (p.groupName || '').toLowerCase().includes('doanh thu')
        ))
      .map(mapCostPlanToLine);
  }, [costPlans, expenseItems]);

  /* ── Active lines ──────────────────────── */
  const sourceLines = useMemo((): PlanLine[] => {
    return activeTab === 'revenue' ? revenueLines : expenseLines;
  }, [activeTab, revenueLines, expenseLines]);

  /* ── Merged lines (server + local - deleted) + schedule overrides in-place ── */
  const activeLines = useMemo((): PlanLine[] => {
    const serverFiltered = sourceLines.filter(l => !localDeletedIds.has(l.id));
    return [...serverFiltered, ...localAddedLines].map(l => {
      const ov = scheduleOverrides[l.id];
      return ov ? { ...l, ...ov } : l;
    });
  }, [sourceLines, localAddedLines, localDeletedIds, scheduleOverrides]);

  const patchLineSchedule = useCallback((lineId: string, patch: Partial<PlanLine>) => {
    if (lineId.startsWith('local-')) {
      setLocalAddedLines(prev => prev.map(l => (l.id === lineId ? { ...l, ...patch } : l)));
      return;
    }
    setScheduleOverrides(prev => ({
      ...prev,
      [lineId]: { ...prev[lineId], ...patch },
    }));
  }, [setLocalAddedLines]);

  const patchLineEntity = useCallback((lineId: string, entityCode: string, entityName: string, priority?: string) => {
    if (lineId.startsWith('local-')) {
      setLocalAddedLines(prev => prev.map(l =>
        l.id === lineId
          ? { ...l, entityCode, entityName, ...(priority != null ? { priority } : {}) }
          : l,
      ));
      if (priority != null) setEditedPriority(prev => ({ ...prev, [lineId]: priority }));
      return;
    }
    const source = activeLines.find(l => l.id === lineId);
    if (!source) return;
    localIdCounter.current += 1;
    const newId = `local-${localIdCounter.current}`;
    setLocalDeletedIds(prev => {
      const next = new Set(prev);
      next.add(lineId);
      return next;
    });
    setLocalAddedLines(prev => [
      ...prev,
      {
        ...source,
        id: newId,
        entityCode,
        entityName,
        priority: priority ?? source.priority,
      },
    ]);
    setEditedLines(prev => {
      const next = { ...prev };
      const planned = next[lineId] ?? source.plannedAmount;
      delete next[lineId];
      next[newId] = planned;
      return next;
    });
    setEditedMustPay(prev => {
      const next = { ...prev };
      const mp = next[lineId] ?? source.mustPay;
      delete next[lineId];
      next[newId] = mp;
      return next;
    });
    setEditedPriority(prev => {
      const next = { ...prev };
      delete next[lineId];
      next[newId] = priority ?? (source.priority || 'Medium');
      return next;
    });
  }, [activeLines, setLocalAddedLines, setLocalDeletedIds]);

  /* ── Add / Copy / Remove handlers ───────── */
  const handleAddLine = useCallback(() => {
    localIdCounter.current += 1;
    const newId = `local-${localIdCounter.current}`;
    const newLine = makeEmptyPlanLine(activeTab, newId);
    const serverCount = sourceLines.filter(l => !localDeletedIds.has(l.id)).length;
    const sel = selectedLineIndex;
    const insertAt =
      sel < 0 || sel >= activeLines.length
        ? activeLines.length
        : sel + 1;
    // localAddedLines sit after server rows — map insert into local array
    const localInsertAt = Math.max(0, insertAt - serverCount);
    setLocalAddedLines(prev => {
      const next = [...prev];
      next.splice(localInsertAt, 0, newLine);
      return next;
    });
    setEditedLines(prev => ({ ...prev, [newId]: 0 }));
    setEditedMustPay(prev => ({ ...prev, [newId]: 0 }));
    setEditedNotes(prev => ({ ...prev, [newId]: '' }));
    setEditedPriority(prev => ({ ...prev, [newId]: 'Medium' }));
    setSelectedLineIndex(insertAt);
  }, [activeTab, activeLines.length, selectedLineIndex, sourceLines, localDeletedIds]);

  const handleCopyLine = useCallback(() => {
    if (selectedLineIndex < 0 || selectedLineIndex >= activeLines.length) return;
    const source = activeLines[selectedLineIndex];
    localIdCounter.current += 1;
    const newId = `local-${localIdCounter.current}`;
    const newLine: PlanLine = {
      ...source,
      id: newId,
    };
    const serverCount = sourceLines.filter(l => !localDeletedIds.has(l.id)).length;
    const insertAt = selectedLineIndex + 1;
    const localInsertAt = Math.max(0, insertAt - serverCount);
    setLocalAddedLines(prev => {
      const next = [...prev];
      next.splice(localInsertAt, 0, newLine);
      return next;
    });
    setEditedLines(prev => ({ ...prev, [newId]: source.plannedAmount }));
    setEditedMustPay(prev => ({ ...prev, [newId]: source.mustPay }));
    setEditedNotes(prev => ({ ...prev, [newId]: '' }));
    setEditedPriority(prev => ({ ...prev, [newId]: source.priority || 'Medium' }));
    setSelectedLineIndex(insertAt);
  }, [selectedLineIndex, activeLines, sourceLines, localDeletedIds]);

  const handleRemoveLine = useCallback((lineId: string) => {
    if (lineId.startsWith('local-')) {
      setLocalAddedLines(prev => prev.filter(l => l.id !== lineId));
      setEditedLines(prev => { const next = { ...prev }; delete next[lineId]; return next; });
      setEditedMustPay(prev => { const next = { ...prev }; delete next[lineId]; return next; });
      setEditedNotes(prev => { const next = { ...prev }; delete next[lineId]; return next; });
    } else {
      setLocalDeletedIds(prev => { const next = new Set(prev); next.add(lineId); return next; });
    }
    setSelectedLineIndex(-1);
  }, []);

  /* ── Per-line field edit handlers ───────── */
  /* ── Edit handlers ─────────────────────── */
  const handleEditStart = useCallback(() => {
    const init: Record<string, number> = {};
    const initMp: Record<string, number> = {};
    const initNote: Record<string, string> = {};
    activeLines.forEach(line => {
      init[line.id] = line.plannedAmount;
      initMp[line.id] = line.mustPay;
      initNote[line.id] = '';
    });
    setEditedLines(init);
    setEditedMustPay(initMp);
    setEditedNotes(initNote);
    clearAllLocalLines();
    setEditMode(true);
  }, [activeLines, clearAllLocalLines]);

  const handleLineEdit = useCallback((id: string, value: number) => {
    setEditedLines(prev => ({ ...prev, [id]: value }));
  }, []);

  const handleMustPayEdit = useCallback((id: string, value: number) => {
    setEditedMustPay(prev => ({ ...prev, [id]: value }));
  }, []);

  const handleNoteEdit = useCallback((id: string, value: string) => {
    setEditedNotes(prev => ({ ...prev, [id]: value }));
  }, []);

  const handlePriorityEdit = useCallback((id: string, value: string) => {
    setEditedPriority(prev => ({ ...prev, [id]: value }));
  }, []);

  const handleCancel = useCallback(() => {
    setEditMode(false);
    setEditedLines({});
    setEditedMustPay({});
    setEditedNotes({});
    clearAllLocalLines();
  }, [clearAllLocalLines]);

  const handleSave = useCallback(async () => {
    setSaving(true);

    try {
      if (planScheduleType === 'Once') {
        // fixed: from === to
      } else if (effectiveTo < effectiveFrom) {
        dispatchAppToast(dispatch, { message: 'Ngày kết thúc phải ≥ ngày áp dụng', type: 'error' });
        return;
      }
      if (needsScheduleValue(planScheduleType) && !scheduleValue.trim()) {
        dispatchAppToast(dispatch, { message: 'Nhập giá trị định kỳ cho loại lịch', type: 'error' });
        return;
      }

      const headerFrom = effectiveFrom;
      const headerTo = planScheduleType === 'Once' ? effectiveFrom : effectiveTo;

      let voucherId = id && id !== 'new' ? id : '';
      if (isCreate) {
        const created = await fpcService.createPlanVoucher({
          voucherDate: localInputToISOWithOffset(voucherDate),
          effectiveFrom: localInputToISOWithOffset(headerFrom),
          effectiveTo: localInputToISOWithOffset(headerTo),
          planScheduleType,
          scheduleValue: needsScheduleValue(planScheduleType) ? scheduleValue.trim() : null,
          planYear,
          planMonth,
          branchCode,
          description,
        });
        voucherId = created.id;
      } else if (voucherId) {
        await fpcService.updatePlanVoucher(voucherId, {
          voucherDate: localInputToISOWithOffset(voucherDate),
          effectiveFrom: localInputToISOWithOffset(headerFrom),
          effectiveTo: localInputToISOWithOffset(headerTo),
          planScheduleType,
          scheduleValue: needsScheduleValue(planScheduleType) ? scheduleValue.trim() : null,
          description,
        });
      }

      const lines = activeLines
        .filter(l => (editedLines[l.id] ?? l.plannedAmount) > 0 || l.entityCode)
        .map(line => {
          const lineType = line.planScheduleType;
          const lineFrom = line.effectiveFrom;
          const lineTo = lineType === 'Once' ? line.effectiveFrom : line.effectiveTo;
          return {
            costCode: line.entityCode,
            plannedAmount: editedLines[line.id] ?? line.plannedAmount,
            mustPay: editedMustPay[line.id] ?? line.mustPay,
            note: editedNotes[line.id] ?? undefined,
            useCustomSchedule: line.useCustomSchedule,
            effectiveFrom: line.useCustomSchedule
              ? localInputToISOWithOffset(lineFrom)
              : null,
            effectiveTo: line.useCustomSchedule
              ? localInputToISOWithOffset(lineTo)
              : null,
            planScheduleType: line.useCustomSchedule ? lineType : null,
            scheduleValue: line.useCustomSchedule && needsScheduleValue(lineType)
              ? line.scheduleValue
              : null,
          };
        });

      for (const line of lines) {
        if (line.useCustomSchedule) {
          if (!line.effectiveFrom || !line.effectiveTo || !line.planScheduleType) {
            dispatchAppToast(dispatch, {
              message: `Dòng ${line.costCode || '?'}: lịch riêng thiếu ngày / loại`,
              type: 'error',
            });
            return;
          }
          if (needsScheduleValue(line.planScheduleType) && !line.scheduleValue) {
            dispatchAppToast(dispatch, {
              message: `Dòng ${line.costCode || '?'}: nhập giá trị định kỳ`,
              type: 'error',
            });
            return;
          }
        }
      }

      await fpcService.batchUpsertCostPlans({
        year: planYear,
        month: planMonth,
        branchCode: branchCode,
        lines,
      });

      if (voucherId) {
        try {
          const exp = await fpcService.expandPlanVoucher(voucherId);
          dispatchAppToast(dispatch, {
            message: `Đã lưu · áp dụng ${exp.linesCreated} dòng lịch`,
            type: 'success',
          });
        } catch {
          dispatchAppToast(dispatch, {
            message: 'Đã lưu kế hoạch (chưa bung lịch — kiểm tra dòng / schedule)',
            type: 'success',
          });
        }
      } else {
        dispatchAppToast(dispatch, { message: 'Đã lưu kế hoạch', type: 'success' });
      }

      setEditMode(false);
      setEditedLines({});
      setEditedMustPay({});
      setEditedNotes({});
      clearAllLocalLines();
      await fetchData(planYear, planMonth, branchCode);
      if (isCreate) {
        navigate('/tc/ke-hoach');
      }
    } catch {
      dispatchAppToast(dispatch, { message: 'Lỗi khi lưu kế hoạch', type: 'error' });
    } finally {
      setSaving(false);
    }
  }, [
    dispatch, activeLines, editedLines, planYear, planMonth, branchCode, voucherDate,
    description, isCreate, fetchData, navigate, clearAllLocalLines, editedMustPay, editedNotes,
    effectiveFrom, effectiveTo, planScheduleType, scheduleValue, id,
  ]);

  /* ── Print ─────────────────────────────── */
  const handlePrint = useCallback(() => {
    const el = document.getElementById('plan-voucher-content');
    if (!el) return;
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write([
      '<html><head><title>Phiếu kế hoạch</title><meta charset="utf-8"><style>',
      'body{font-family:Arial,sans-serif;padding:20px;color:#1e293b}',
      'table{width:100%;border-collapse:collapse;margin:16px 0;font-size:12px}',
      'th,td{padding:8px 12px;border:1px solid #e2e8f0;text-align:left}',
      'th{background:#f8fafc;font-weight:600;font-size:11px;text-transform:uppercase}',
      'h1{font-size:22px;color:#8b5cf6;margin:0 0 4px}',
      'h2{font-size:16px;color:#64748b;font-weight:400;margin:0 0 16px}',
      '.right{text-align:right}.money{font-family:monospace;text-align:right}',
      '.positive{color:#059669}.negative{color:#ef4444}',
      '.footer{display:flex;justify-content:flex-end;gap:24px;padding:12px;margin-top:12px}',
      '</style></head><body>',
      `<h1>Phiếu kế hoạch — ${activeTab === 'revenue' ? 'Kế hoạch thu' : 'Kế hoạch chi'} Tháng ${planMonth}/${planYear}</h1>`,
      `<h2>Ngày in: ${new Date().toLocaleString('vi-VN')}</h2>`,
      el.innerHTML,
      '</body></html>',
    ].join('\n'));
    win.document.close();
    win.print();
  }, [activeTab, planMonth, planYear]);

  /* ── Computed totals ───────────────────── */
  const totalPlanned = activeLines.reduce((s, l) => s + (editMode ? (editedLines[l.id] ?? l.plannedAmount) : l.plannedAmount), 0);
  const totalMustPay = activeLines.reduce((s, l) => s + l.mustPay, 0);
  const activeCount = activeLines.filter(l => (editMode ? (editedLines[l.id] ?? l.plannedAmount) : l.plannedAmount) > 0).length;

  const dateLabel = `Tháng ${planMonth}/${planYear}`;
  const periodMatch = loadedPeriod.year === planYear && loadedPeriod.month === planMonth;

  /* ── Render ────────────────────────────── */
  return (
    <div className={styles.page} data-form-page data-voucher-form-shell data-testid={`${TEST_ID}-page`}>
      {/* ── Toolbar header ── */}
      <div className={styles.pageFormHeader}>
        <div className={styles.stickyTop}>
          <div className={styles.pageHeader}>
            {/* Row 1 — Quay lại + actions (parity PT) */}
            <div className={styles.toolbarRow}>
              <button className={styles.backBtn} onClick={() => navigate('/tc/ke-hoach')} type="button">
                <i className="fas fa-arrow-left" aria-hidden /> Quay lại
              </button>
              <FormActions align="end">
                {editMode ? (
                  <>
                    <Button onClick={handleCancel} data-testid={`${TEST_ID}-cancel-btn`}>
                      <i className="fas fa-times" /> Hủy
                    </Button>
                    <Button variant="primary" onClick={handleSave} disabled={saving} data-testid={`${TEST_ID}-save-btn`}>
                      <i className={`fas ${saving ? 'fa-spinner fa-spin' : 'fa-save'}`} />
                      {saving ? ' Đang lưu...' : ' Lưu'}
                    </Button>
                  </>
                ) : (
                  <>
                    <Button variant="primary" onClick={handleEditStart} data-testid={`${TEST_ID}-edit-btn`}>
                      <i className="fas fa-edit" /> Sửa
                    </Button>
                    <Button onClick={handlePrint} data-testid={`${TEST_ID}-print-btn`}>
                      <i className="fas fa-print" /> In
                    </Button>
                    <Button onClick={() => fetchData(planYear, planMonth, branchCode)} data-testid={`${TEST_ID}-refresh-btn`}>
                      <i className="fas fa-redo" /> Làm mới
                    </Button>
                  </>
                )}
              </FormActions>
            </div>
            {/* Row 2 — Title */}
            <h1 className={styles.title}>
              {isCreate ? 'Tạo phiếu kế hoạch' : (voucher ? `Phiếu ${voucher.code}` : 'Phiếu kế hoạch')}
            </h1>
            {/* Z1h — hint */}
            {!isCreate && !editMode && (
              <div className={styles.viewModeHint} data-testid={`${TEST_ID}-view-hint`}>
                <i className="fas fa-eye" /> Chế độ xem — nhấn <strong>Sửa</strong> để chỉnh sửa
              </div>
            )}
            {editMode && (
              <div className={styles.readOnlyHint} data-testid={`${TEST_ID}-edit-hint`}>
                <i className="fas fa-pen" /> Đang {isCreate ? 'tạo mới' : 'chỉnh sửa'} — Lưu hoặc Hủy
              </div>
            )}
          </div>
        </div>
      </div>

      {/* ── Scrollable content ── */}
      <div className={`${styles.pageFormScroll}${!editMode ? ` ${styles.viewDisabled}` : ''}`} id="plan-voucher-content">
        {/* ── Voucher loading ── */}
        {voucherLoading && (
          <FormSkeleton headerRows={2} lineRows={3} data-testid={`${TEST_ID}-form-skeleton`} />
        )}

        {!voucherLoading && <>
          {/* ── Header section with compact toggle ── */}
          <div
            className={styles.section}
            data-testid={`${TEST_ID}-section-header`}
          >
            <div className={styles.sectionTitleRow}>
              <h2 className={styles.sectionTitle}>THÔNG TIN PHIẾU KẾ HOẠCH</h2>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                <span className={styles.sectionBadge}>{dateLabel}</span>
                <button
                  type="button"
                  className={styles.headerToggleBtn}
                  data-testid={`${TEST_ID}-header-${headerExpanded ? 'collapse' : 'expand'}`}
                  aria-expanded={headerExpanded}
                  onClick={() => setHeaderExpanded(v => !v)}
                >
                  <span className={styles.headerToggleIcon} aria-hidden>
                    <i className={headerExpanded ? 'fas fa-chevron-up' : 'fas fa-chevron-down'} />
                  </span>
                  {headerExpanded ? 'Thu gọn' : 'Mở rộng'}
                </button>
              </div>
            </div>

            {/* Row A+B: 5 cột — Ngày lập · Loại CT · Số phiếu · Loại lịch · Ngày cố định | Tần suất */}
            <FormRowCol cols={4} rowsBySize={HEADER_5COL} data-testid={`${TEST_ID}-header-labels`}>
              <FormRowCol.Item>
                <label className={styles.label}>Ngày lập<RequiredMark /></label>
              </FormRowCol.Item>
              <FormRowCol.Item>
                <label className={styles.label}>Loại chứng từ<RequiredMark /></label>
              </FormRowCol.Item>
              <FormRowCol.Item hidden={!headerExpanded}>
                <label className={styles.label}>Số phiếu</label>
              </FormRowCol.Item>
              <FormRowCol.Item>
                <label className={styles.label}>Loại lịch<RequiredMark /></label>
              </FormRowCol.Item>
              <FormRowCol.Item>
                <label className={styles.label}>
                  {scheduleKind === 'fixed' ? <>Ngày cố định<RequiredMark /></> : <>Tần suất lặp lại<RequiredMark /></>}
                </label>
              </FormRowCol.Item>
            </FormRowCol>

            <FormRowCol cols={4} rowsBySize={HEADER_5COL} data-testid={`${TEST_ID}-header-inputs`}>
              <FormRowCol.Item variant="field">
                <Input
                  type="date"
                  value={voucherDate}
                  onChange={e => setVoucherDate(e.target.value)}
                  max={todayDateStr()}
                  data-testid={`${TEST_ID}-voucherDate`}
                />
              </FormRowCol.Item>
              <FormRowCol.Item variant="field">
                <Select
                  value={voucherType}
                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setVoucherType(e.target.value as VoucherType)}
                  options={VOUCHER_TYPE_OPTIONS}
                  data-testid={`${TEST_ID}-voucherType`}
                />
              </FormRowCol.Item>
              <FormRowCol.Item variant="field" hidden={!headerExpanded}>
                <Input
                  value={voucherCode}
                  onChange={e => setVoucherCode(e.target.value)}
                  placeholder="PKH-YYYYMMDD-NNNN"
                  readOnly={!isCreate}
                  data-testid={`${TEST_ID}-voucherCode`}
                />
              </FormRowCol.Item>
              <FormRowCol.Item variant="field">
                <Select
                  value={scheduleKind}
                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {
                    const kind = e.target.value as ScheduleKind;
                    if (kind === 'fixed') {
                      setPlanScheduleType('Once');
                      setScheduleValue('');
                      setEffectiveTo(effectiveFrom);
                    } else {
                      setPlanScheduleType('ByDay');
                      setScheduleValue('');
                      if (effectiveTo < effectiveFrom) {
                        const [y, m] = effectiveFrom.split('-').map(Number);
                        setEffectiveTo(monthEndDateStr(y, m));
                      }
                    }
                  }}
                  options={SCHEDULE_KIND_OPTIONS}
                  data-testid={`${TEST_ID}-scheduleKind`}
                />
              </FormRowCol.Item>
              <FormRowCol.Item variant="field">
                {scheduleKind === 'fixed' ? (
                  <Input
                    type="date"
                    value={effectiveFrom}
                    onChange={e => {
                      handleEffectiveFromChange(e.target.value);
                      setEffectiveTo(e.target.value);
                    }}
                    data-testid={`${TEST_ID}-fixedDate`}
                  />
                ) : (
                  <Select
                    value={planScheduleType === 'Once' ? 'ByDay' : planScheduleType}
                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {
                      const next = e.target.value as PlanScheduleType;
                      setPlanScheduleType(next);
                      if (next === 'ByDay') setScheduleValue('');
                      else if (next === 'ByDayOfMonth') setScheduleValue(scheduleValue === 'Last' || (parseInt(scheduleValue, 10) >= 1 && parseInt(scheduleValue, 10) <= 28) ? scheduleValue : '1');
                      else if (next === 'ByDayOfWeek') setScheduleValue(scheduleValue || '1');
                      else if (next === 'ByDayOfYear') setScheduleValue(scheduleValue.includes('-') ? scheduleValue : '01-01');
                    }}
                    options={RECURRING_FREQ_OPTIONS}
                    data-testid={`${TEST_ID}-planScheduleType`}
                  />
                )}
              </FormRowCol.Item>
            </FormRowCol>

            {/* Row định kỳ: Từ · Đến · Giá trị · (pad) · (pad) — luôn 5 cột */}
            {scheduleKind === 'recurring' && (
              <>
                <FormRowCol cols={4} rowsBySize={HEADER_5COL} data-testid={`${TEST_ID}-header-schedule-labels`}>
                  <FormRowCol.Item>
                    <label className={styles.label}>Ngày áp dụng<RequiredMark /></label>
                  </FormRowCol.Item>
                  <FormRowCol.Item>
                    <label className={styles.label}>Ngày kết thúc<RequiredMark /></label>
                  </FormRowCol.Item>
                  <FormRowCol.Item>
                    <label className={styles.label}>
                      {planScheduleType === 'ByDayOfMonth' ? 'Ngày trong tháng' : planScheduleType === 'ByDayOfWeek' ? 'Ngày trong tuần' : planScheduleType === 'ByDayOfYear' ? 'Ngày trong năm' : 'Giá trị'}
                      {needsScheduleValue(planScheduleType) ? <RequiredMark /> : null}
                    </label>
                  </FormRowCol.Item>
                  <FormRowCol.Item>
                    <label className={styles.label}>{planScheduleType === 'ByDayOfMonth' ? 'Kiểu ngày' : '\u00a0'}</label>
                  </FormRowCol.Item>
                  <FormRowCol.Item>
                    <label className={styles.label}>{'\u00a0'}</label>
                  </FormRowCol.Item>
                </FormRowCol>
                <FormRowCol cols={4} rowsBySize={HEADER_5COL} data-testid={`${TEST_ID}-header-schedule`}>
                  <FormRowCol.Item variant="field">
                    <Input
                      type="date"
                      value={effectiveFrom}
                      onChange={e => handleEffectiveFromChange(e.target.value)}
                      data-testid={`${TEST_ID}-effectiveFrom`}
                    />
                  </FormRowCol.Item>
                  <FormRowCol.Item variant="field">
                    <Input
                      type="date"
                      value={effectiveTo}
                      min={effectiveFrom}
                      onChange={e => setEffectiveTo(e.target.value)}
                      data-testid={`${TEST_ID}-effectiveTo`}
                    />
                  </FormRowCol.Item>
                  <FormRowCol.Item variant="field">
                    {planScheduleType === 'ByDay' ? (
                      <Input value="Mỗi ngày trong khoảng" readOnly data-testid={`${TEST_ID}-scheduleValue`} />
                    ) : planScheduleType === 'ByDayOfWeek' ? (
                      <Select
                        value={scheduleValue.split(',')[0] || '1'}
                        onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setScheduleValue(e.target.value)}
                        options={WEEKDAY_OPTIONS}
                        data-testid={`${TEST_ID}-scheduleValue`}
                      />
                    ) : planScheduleType === 'ByDayOfMonth' ? (
                      scheduleValue === 'Last' ? (
                        <Input value="Ngày cuối tháng" readOnly data-testid={`${TEST_ID}-scheduleValue`} />
                      ) : (
                        <Input
                          type="number"
                          min={1}
                          max={28}
                          value={scheduleValue || '1'}
                          onChange={e => {
                            const n = Math.min(28, Math.max(1, parseInt(e.target.value, 10) || 1));
                            setScheduleValue(String(n));
                          }}
                          data-testid={`${TEST_ID}-scheduleValue`}
                        />
                      )
                    ) : (
                      <Input
                        type="text"
                        placeholder="MM-DD"
                        value={scheduleValue}
                        onChange={e => setScheduleValue(e.target.value)}
                        data-testid={`${TEST_ID}-scheduleValue`}
                      />
                    )}
                  </FormRowCol.Item>
                  <FormRowCol.Item variant="field">
                    {planScheduleType === 'ByDayOfMonth' ? (
                      <Select
                        value={scheduleValue === 'Last' ? 'Last' : 'Day'}
                        onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {
                          setScheduleValue(e.target.value === 'Last' ? 'Last' : '1');
                        }}
                        options={MONTH_MODE_OPTIONS}
                        data-testid={`${TEST_ID}-monthMode`}
                      />
                    ) : (
                      <Input value="" readOnly tabIndex={-1} aria-hidden style={{ visibility: 'hidden' }} />
                    )}
                  </FormRowCol.Item>
                  <FormRowCol.Item variant="field">
                    <Input value="" readOnly tabIndex={-1} aria-hidden style={{ visibility: 'hidden' }} />
                  </FormRowCol.Item>
                </FormRowCol>
              </>
            )}

            {/* Row 2: 5-col merged — Chi nhánh 2fr + Diễn giải 3fr */}
            <div className={styles.mixedRow} data-testid={`${TEST_ID}-header-branch-desc`}>
              <div className={styles.mixedItem}>
                <label className={styles.label}>Chi nhánh / Đơn vị</label>
                <SearchInput
                  config={companySearchConfig}
                  className={headerLookupClassName}
                  value={branchCode}
                  primaryDisplay={selectedCompany?.code ?? branchCode}
                  secondaryDisplay={selectedCompany?.name ?? ''}
                  onChange={(item) => handleBranchChange(item as ActiveCompanyItem)}
                  onClear={() => handleBranchChange(null)}
                  showLabel={false}
                  showSecondaryInput
                  placeholder="Chi nhánh..."
                  data-testid={`${TEST_ID}-branch`}
                />
              </div>
              {headerExpanded && (
                <div className={styles.mixedItem}>
                  <label className={styles.label}>Diễn giải</label>
                  <Input
                    value={description}
                    onChange={e => setDescription(e.target.value)}
                    placeholder="Nhập mô tả kế hoạch"
                    data-testid={`${TEST_ID}-description`}
                  />
                </div>
              )}
            </div>
          </div>

          {/* ── Loading ── */}
          {loading && (
            <FormSkeleton headerRows={1} lineRows={4} showFooter={false} data-testid={`${TEST_ID}-data-skeleton`} />
          )}

          {!loading && !periodMatch && (
            <div style={{ textAlign: 'center', padding: 32, color: '#94a3b8' }}>
              <i className="fas fa-sync" style={{ fontSize: 24, display: 'block', marginBottom: 8 }} />
              Đang tải kỳ {dateLabel}...
            </div>
          )}

          {!loading && periodMatch && (
            <>
              <div className={`${styles.section} ${styles.tabContentSection}`} style={{ padding: 0 }}>
                <div className={styles.tabBar}>
                  <button
                    className={`${styles.tabBtn} ${activeTab === 'revenue' ? styles.tabActiveRevenue : ''}`}
                    onClick={() => { setActiveTab('revenue'); setSelectedLineIndex(-1); }}
                    type="button"
                  >
                    <i className="fas fa-arrow-up" style={{ marginRight: 6 }} />
                    Kế hoạch thu
                  </button>
                  <button
                    className={`${styles.tabBtn} ${activeTab === 'expense' ? styles.tabActiveExpense : ''}`}
                    onClick={() => { setActiveTab('expense'); setSelectedLineIndex(-1); }}
                    type="button"
                  >
                    <i className="fas fa-arrow-down" style={{ marginRight: 6 }} />
                    Kế hoạch chi
                  </button>
                </div>

                <div className={styles.tabContentBody}>
                  {/* Empty state */}
                  {activeLines.length === 0 && (
                    <div style={{ padding: '32px 0', textAlign: 'center', color: '#94a3b8' }}>
                      <i className="fas fa-inbox" style={{ fontSize: 32, display: 'block', marginBottom: 12 }} />
                      {branchCode
                        ? `Chưa có dữ liệu cho ${activeTab === 'revenue' ? 'kế hoạch thu' : 'kế hoạch chi'} kỳ ${dateLabel} tại chi nhánh đã chọn. `
                        : `Chưa có dữ liệu cho ${activeTab === 'revenue' ? 'kế hoạch thu' : 'kế hoạch chi'} kỳ ${dateLabel}. `}
                      {editMode ? <>Nhấn <strong>"Thêm dòng"</strong> để khai báo.</> : <>Nhấn <strong>Sửa</strong> để khai báo.</>}
                    </div>
                  )}

                  {activeLines.length > 0 && (
                    <>
                      {/* Lines table */}
                      <div className={styles.tableWrapper}>
                        <table className={styles.linesTable}>
                          <thead>
                            <tr>
                              <th style={{ width: 36 }}>STT</th>
                              <th className={styles.thEntityLookup}>
                                {entityColumnTitle(voucherType, activeTab)}
                              </th>
                              <th style={{ width: 130 }}>Ưu tiên</th>
                              <th style={{ width: 88 }} title="Bật để nhập lịch riêng trên dòng">Lịch riêng</th>
                              {editMode ? activeTab === 'revenue' ? (
                                <>
                                  <th className={styles.colRight} style={{ width: 160 }}>Kế hoạch thu</th>
                                  <th style={{ width: 140 }}>Ghi chú</th>
                                  <th style={{ width: 40 }} />
                                </>
                              ) : (
                                <>
                                  <th className={styles.colRight} style={{ width: 160 }}>Kế hoạch chi</th>
                                  <th className={styles.colRight} style={{ width: 160 }}>Phải chi</th>
                                  <th style={{ width: 140 }}>Ghi chú</th>
                                  <th style={{ width: 40 }} />
                                </>
                              ) : activeTab === 'revenue' ? (
                                <>
                                  <th className={styles.colRight} style={{ width: 160 }}>Dự kiến thu</th>
                                </>
                              ) : (
                                <>
                                  <th className={styles.colRight} style={{ width: 140 }}>Phải chi</th>
                                  <th className={styles.colRight} style={{ width: 140 }}>Dự chi</th>
                                </>
                              )}
                            </tr>
                          </thead>
                          <tbody>
                            {activeLines.map((line, idx) => {
                              const globalIdx = idx;
                              const isSelected = selectedLineIndex === globalIdx;
                              const rowClass = [
                                styles.lineRow,
                                isSelected ? styles.lineRowSelected : '',
                              ].filter(Boolean).join(' ');

                              return (
                                <React.Fragment key={line.id}>
                                <tr
                                  className={rowClass}
                                  data-testid={`${TEST_ID}-line-${globalIdx}`}
                                  onClick={(e) => {
                                    setSelectedLineIndex(globalIdx);
                                    if (isLineRowFieldTarget(e.target as HTMLElement)) return;
                                  }}
                                >
                                  <td style={{ textAlign: 'center', color: '#94a3b8', fontWeight: 500 }}>{globalIdx + 1}</td>
                                  {/* Entity lookup — dual mã + tên (parity PT Đối tượng) */}
                                  <td
                                    className={styles.tdEntityLookup}
                                    onClick={e => e.stopPropagation()}
                                  >
                                    {editMode ? (
                                      voucherType === 'ma-chi-phi' ? (
                                        <SearchInput
                                          config={costCodeSearchConfig}
                                          className={lineLookupClassName}
                                          value={line.entityCode}
                                          primaryDisplay={line.entityCode}
                                          secondaryDisplay={line.entityName}
                                          onChange={(item) => {
                                            const it = item as ExpenseItemLookupItem;
                                            patchLineEntity(line.id, it.code, it.name);
                                          }}
                                          onClear={() => patchLineEntity(line.id, '', '')}
                                          showLabel={false}
                                          showSecondaryInput
                                          placeholder={entityLookupPlaceholder(voucherType)}
                                          data-testid={`${TEST_ID}-line-${globalIdx}-costCode`}
                                        />
                                      ) : (
                                        <SearchInput
                                          config={voucherType === 'doi-tuong' ? objectSearchConfig : companySearchConfig}
                                          className={lineLookupClassName}
                                          value={line.entityCode}
                                          primaryDisplay={line.entityCode}
                                          secondaryDisplay={line.entityName}
                                          onChange={(item) => {
                                            const it = item as ActiveCompanyItem;
                                            patchLineEntity(line.id, it.code ?? it.id, it.name);
                                          }}
                                          onClear={() => patchLineEntity(line.id, '', '')}
                                          showLabel={false}
                                          showSecondaryInput
                                          placeholder={entityLookupPlaceholder(voucherType)}
                                          data-testid={`${TEST_ID}-line-${globalIdx}-entity`}
                                        />
                                      )
                                    ) : (
                                      line.entityCode
                                        ? (
                                          <span className={styles.entityViewDual}>
                                            <span className={styles.entityViewCode}>{line.entityCode}</span>
                                            <span className={styles.entityViewName}>{line.entityName || '—'}</span>
                                          </span>
                                        )
                                        : <span style={{ color: '#94a3b8' }}>—</span>
                                    )}
                                  </td>
                                  {/* Ưu tiên — LOOKUP_STATIC common Select (erp-form-context) */}
                                  <td className={styles.tdPriority}>
                                    {editMode ? (
                                      <Select
                                        fullWidth
                                        size="medium"
                                        value={editedPriority[line.id] ?? (line.priority || 'Medium')}
                                        onChange={(e: React.ChangeEvent<HTMLSelectElement>) =>
                                          handlePriorityEdit(line.id, e.target.value)
                                        }
                                        options={
                                          priorityClasses.length > 0
                                            ? priorityClasses.map(opt => ({ value: opt.code, label: opt.name }))
                                            : [
                                              { value: 'Critical', label: 'Rất cao' },
                                              { value: 'High', label: 'Cao' },
                                              { value: 'Medium', label: 'Trung bình' },
                                              { value: 'Low', label: 'Thấp' },
                                            ]
                                        }
                                        data-testid={`${TEST_ID}-priority-${globalIdx}`}
                                      />
                                    ) : line.priority ? (
                                      (() => {
                                        const meta = resolvePriorityMeta(line.priority, priorityClasses);
                                        return (
                                          <span style={{
                                            padding: '1px 6px',
                                            borderRadius: 4,
                                            fontSize: 10,
                                            fontWeight: 600,
                                            background: meta.background,
                                            color: meta.color,
                                          }}>
                                            {meta.label}
                                          </span>
                                        );
                                      })()
                                    ) : (
                                      <span style={{ color: '#94a3b8' }}>—</span>
                                    )}
                                  </td>
                                  <td
                                    style={{ textAlign: 'center' }}
                                    onClick={e => e.stopPropagation()}
                                  >
                                    {editMode ? (
                                      <input
                                        type="checkbox"
                                        checked={line.useCustomSchedule}
                                        onChange={e => {
                                          const on = e.target.checked;
                                          e.stopPropagation();
                                          patchLineSchedule(line.id, {
                                            useCustomSchedule: on,
                                            effectiveFrom: on ? (line.effectiveFrom || effectiveFrom) : line.effectiveFrom,
                                            effectiveTo: on
                                              ? (planScheduleType === 'Once' ? (line.effectiveFrom || effectiveFrom) : (line.effectiveTo || effectiveTo))
                                              : line.effectiveTo,
                                            planScheduleType: on ? (line.planScheduleType || planScheduleType) : line.planScheduleType,
                                            scheduleValue: on ? (line.scheduleValue || scheduleValue) : line.scheduleValue,
                                          });
                                        }}
                                        onClick={e => e.stopPropagation()}
                                        data-testid={`${TEST_ID}-line-${globalIdx}-custom-schedule`}
                                        title="Lịch riêng"
                                      />
                                    ) : (
                                      <span style={{ fontSize: 11, color: line.useCustomSchedule ? '#0f766e' : '#94a3b8' }}>
                                        {line.useCustomSchedule ? 'Riêng' : 'Phiếu'}
                                      </span>
                                    )}
                                  </td>
                                  {editMode ? activeTab === 'revenue' ? (
                                    <>
                                      {/* Kế hoạch thu */}
                                          <td>
                                            <MoneyInput
                                              className={styles.lineInput}
                                              value={editedLines[line.id] ?? line.plannedAmount}
                                              onChange={v => handleLineEdit(line.id, v)}
                                            />
                                          </td>
                                          {/* Ghi chú */}
                                          <td>
                                            <Input
                                              className={`${styles.lineInput} ${styles.lineInputNote}`}
                                              value={editedNotes[line.id] ?? ''}
                                              onChange={e => handleNoteEdit(line.id, e.target.value)}
                                              placeholder="Nhập ghi chú..."
                                            />
                                          </td>
                                          {/* Xóa */}
                                          <td className={styles.tdDel}>
                                            <button
                                              type="button"
                                              className={styles.btnDeleteLine}
                                              onClick={e => { e.stopPropagation(); handleRemoveLine(line.id); }}
                                              title="Xóa dòng"
                                              data-testid={`${TEST_ID}-line-${globalIdx}-delete`}
                                            >
                                              <i className="fas fa-trash-alt" />
                                            </button>
                                          </td>
                                        </>
                                      ) : (
                                        <>
                                          {/* Kế hoạch chi */}
                                          <td>
                                            <MoneyInput
                                              className={styles.lineInput}
                                              value={editedLines[line.id] ?? line.plannedAmount}
                                              onChange={v => handleLineEdit(line.id, v)}
                                            />
                                          </td>
                                          {/* Phải chi */}
                                          <td>
                                            <MoneyInput
                                              className={styles.lineInput}
                                              value={editedMustPay[line.id] ?? line.mustPay}
                                              onChange={v => handleMustPayEdit(line.id, v)}
                                            />
                                          </td>
                                          {/* Ghi chú */}
                                          <td>
                                            <Input
                                              className={`${styles.lineInput} ${styles.lineInputNote}`}
                                              value={editedNotes[line.id] ?? ''}
                                              onChange={e => handleNoteEdit(line.id, e.target.value)}
                                              placeholder="Nhập ghi chú..."
                                            />
                                          </td>
                                          {/* Xóa */}
                                          <td className={styles.tdDel}>
                                            <button
                                              type="button"
                                              className={styles.btnDeleteLine}
                                              onClick={e => { e.stopPropagation(); handleRemoveLine(line.id); }}
                                              title="Xóa dòng"
                                              data-testid={`${TEST_ID}-line-${globalIdx}-delete`}
                                            >
                                              <i className="fas fa-trash-alt" />
                                            </button>
                                          </td>
                                        </>
                                      ) : activeTab === 'revenue' ? (
                                        <>
                                          <td className={styles.colAmount}>{fVnd(line.plannedAmount)}</td>
                                        </>
                                      ) : (
                                        <>
                                          <td className={styles.colAmount}>{fVnd(line.mustPay)}</td>
                                          <td className={styles.colAmount}>{fVnd(line.plannedAmount)}</td>
                                        </>
                                      )}
                                    </tr>
                                {line.useCustomSchedule && (
                                  <tr
                                    className={styles.scheduleSubRow}
                                    data-testid={`${TEST_ID}-line-${globalIdx}-schedule`}
                                    onClick={e => e.stopPropagation()}
                                  >
                                    <td />
                                    <td colSpan={editMode ? (activeTab === 'revenue' ? 6 : 7) : (activeTab === 'revenue' ? 3 : 4)}>
                                      {editMode ? (
                                        <div className={styles.scheduleSubFields}>
                                          <label>
                                            <span>Loại lịch</span>
                                            <Select
                                              value={toScheduleKind(line.planScheduleType)}
                                              onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {
                                                const kind = e.target.value as ScheduleKind;
                                                if (kind === 'fixed') {
                                                  patchLineSchedule(line.id, {
                                                    planScheduleType: 'Once',
                                                    scheduleValue: '',
                                                    effectiveTo: line.effectiveFrom,
                                                  });
                                                } else {
                                                  patchLineSchedule(line.id, {
                                                    planScheduleType: 'ByDay',
                                                    scheduleValue: '',
                                                  });
                                                }
                                              }}
                                              options={SCHEDULE_KIND_OPTIONS}
                                            />
                                          </label>
                                          {toScheduleKind(line.planScheduleType) === 'fixed' ? (
                                            <label>
                                              <span>Ngày cố định</span>
                                              <Input
                                                type="date"
                                                value={line.effectiveFrom}
                                                onChange={e => patchLineSchedule(line.id, {
                                                  effectiveFrom: e.target.value,
                                                  effectiveTo: e.target.value,
                                                })}
                                              />
                                            </label>
                                          ) : (
                                            <>
                                              <label>
                                                <span>Tần suất</span>
                                                <Select
                                                  value={line.planScheduleType === 'Once' ? 'ByDay' : line.planScheduleType}
                                                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {
                                                    const next = e.target.value as PlanScheduleType;
                                                    patchLineSchedule(line.id, {
                                                      planScheduleType: next,
                                                      scheduleValue: next === 'ByDay' ? '' : (next === 'ByDayOfYear' ? '01-01' : next === 'ByDayOfMonth' ? '1' : '1'),
                                                    });
                                                  }}
                                                  options={RECURRING_FREQ_OPTIONS}
                                                />
                                              </label>
                                              <label>
                                                <span>Từ</span>
                                                <Input
                                                  type="date"
                                                  value={line.effectiveFrom}
                                                  onChange={e => patchLineSchedule(line.id, { effectiveFrom: e.target.value })}
                                                />
                                              </label>
                                              <label>
                                                <span>Đến</span>
                                                <Input
                                                  type="date"
                                                  value={line.effectiveTo}
                                                  min={line.effectiveFrom}
                                                  onChange={e => patchLineSchedule(line.id, { effectiveTo: e.target.value })}
                                                />
                                              </label>
                                              {line.planScheduleType === 'ByDayOfMonth' && (
                                                <label>
                                                  <span>Kiểu ngày</span>
                                                  <Select
                                                    value={line.scheduleValue === 'Last' ? 'Last' : 'Day'}
                                                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) =>
                                                      patchLineSchedule(line.id, {
                                                        scheduleValue: e.target.value === 'Last' ? 'Last' : '1',
                                                      })
                                                    }
                                                    options={MONTH_MODE_OPTIONS}
                                                  />
                                                </label>
                                              )}
                                              {needsScheduleValue(line.planScheduleType) && line.planScheduleType !== 'ByDayOfMonth' && (
                                                <label>
                                                  <span>Giá trị</span>
                                                  {line.planScheduleType === 'ByDayOfWeek' ? (
                                                    <Select
                                                      value={line.scheduleValue.split(',')[0] || '1'}
                                                      onChange={(e: React.ChangeEvent<HTMLSelectElement>) =>
                                                        patchLineSchedule(line.id, { scheduleValue: e.target.value })
                                                      }
                                                      options={WEEKDAY_OPTIONS}
                                                    />
                                                  ) : (
                                                    <Input
                                                      placeholder="MM-DD"
                                                      value={line.scheduleValue}
                                                      onChange={e => patchLineSchedule(line.id, { scheduleValue: e.target.value })}
                                                    />
                                                  )}
                                                </label>
                                              )}
                                              {line.planScheduleType === 'ByDayOfMonth' && line.scheduleValue !== 'Last' && (
                                                <label>
                                                  <span>Ngày (1–28)</span>
                                                  <Input
                                                    type="number"
                                                    min={1}
                                                    max={28}
                                                    value={line.scheduleValue || '1'}
                                                    onChange={e => {
                                                      const n = Math.min(28, Math.max(1, parseInt(e.target.value, 10) || 1));
                                                      patchLineSchedule(line.id, { scheduleValue: String(n) });
                                                    }}
                                                  />
                                                </label>
                                              )}
                                            </>
                                          )}
                                        </div>
                                      ) : (
                                        <span className={styles.scheduleSubView}>
                                          {scheduleTypeLabel(line.planScheduleType)}
                                          {' · '}
                                          {line.planScheduleType === 'Once'
                                            ? line.effectiveFrom
                                            : `${line.effectiveFrom} → ${line.effectiveTo}`}
                                          {' · '}
                                          {scheduleValueLabel(line.planScheduleType, line.scheduleValue)}
                                        </span>
                                      )}
                                    </td>
                                  </tr>
                                )}
                                </React.Fragment>
                                  );
                              })}
                          </tbody>
                        </table>
                      </div>
                    </>
                  )}

                  {/* Add / Copy — luôn hiện khi edit (parity PT · kể cả 0 dòng) */}
                  {editMode && (
                    <div className={styles.linesActions}>
                      <button
                        type="button"
                        className={styles.btnAddLine}
                        data-testid={`${TEST_ID}-add-line-btn`}
                        onClick={handleAddLine}
                      >
                        <i className="fas fa-plus" style={{ marginRight: 6 }} />
                        Thêm dòng
                      </button>
                      <button
                        type="button"
                        className={styles.btnCopyLine}
                        data-testid={`${TEST_ID}-copy-line-btn`}
                        onClick={handleCopyLine}
                        disabled={selectedLineIndex < 0 || activeLines.length === 0}
                      >
                        <i className="fas fa-copy" style={{ marginRight: 6 }} />
                        Sao chép dòng
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </>
          )}
        </>}
      </div>

      {/* ── Footer — luôn hiện khi form ready ── */}
      {!voucherLoading && (
        <div className={styles.pageFormFooter}>
          <div className={styles.footer}>
            <div className={styles.footerLeft}>
              <label className={styles.footerLabel}>Mức xử lý</label>
              <Select
                className={styles.footerSelect}
                value={processingLevel}
                onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setProcessingLevel(e.target.value)}
                options={PROCESSING_LEVEL_OPTIONS}
                disabled={!editMode}
                data-testid={`${TEST_ID}-processingLevel`}
              />
              <span className={styles.footerTypeLabel} style={{
                color: activeTab === 'revenue' ? '#059669' : '#92400e',
                fontWeight: 600,
                fontSize: 14,
                padding: '4px 10px',
                borderRadius: 4,
                background: activeTab === 'revenue' ? '#d1fae5' : '#fef3c7',
              }}>
                {activeTab === 'revenue' ? 'Kế hoạch thu' : 'Kế hoạch chi'}
              </span>
              <span style={{ fontSize: 13, color: '#64748b' }}>
                {editMode ? `Đang chỉnh sửa · ${activeCount} dòng` : `${activeCount} dòng`}
              </span>
            </div>
            <div className={styles.totalBlock}>
              {activeTab === 'expense' && (
                <LabelMoney
                  label="Phải chi:"
                  value={totalMustPay}
                  variant="footer"
                  data-testid={`${TEST_ID}-footer-totalMustPay`}
                />
              )}
              <LabelMoney
                label={activeTab === 'revenue' ? 'Dự kiến thu:' : 'Kế hoạch chi:'}
                value={totalPlanned}
                variant="footer"
                emphasize
                data-testid={`${TEST_ID}-footer-totalPlanned`}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PlanVoucherPage;
